/* @lc app=leetcode id=3319 lang=kotlin */ class Solution { fun kthLargestPerfectSubtree(root: TreeNode?, k: Int): Int = generateSequence(listOf(root!!)) { f -> f.flatMap { listOfNotNull(it.left, it.right) }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> HashMap<TreeNode, Int>().let { h -> order.map { n -> (n.left?.let { h[it]!! } ?: 0).let { l -> (n.right?.let { h[it]!! } ?: 0).let { r -> (if (l >= 0 && l == r) l + 1 else -1).also { h[n] = it } } } }.filter { it > 0 }.map { (1 shl it) - 1 }.sortedDescending().getOrNull(k - 1) ?: -1 } } }